import React, { useEffect, useState, ChangeEvent } from 'react';
import { Select, SelectItem } from '@carbon/react';
import { uniqueId } from 'lodash';

type FlowPropertyValue = string | string[] | boolean | number | Record<string, string>;

type FlowValue = {
  scopes?: string[];
  refreshUrl?: string;
  tokenUrl?: string;
  authorizationUrl?: string;
  clientId?: string;
  clientSecret?: string;
  grantType?: string;
  responseType?: string;
  redirectUri?: string;
  state?: string;
  audience?: string;
  resource?: string;
  extensions?: Record<string, string>;
  [key: string]: FlowPropertyValue | undefined;
};

type FlowsType = {
  [flowName: string]: FlowValue;
}

type TestToolSecurityFlowsProps = {
  flows: FlowsType;
  currentFlow: string | null;
  onChange?: Function;
}

function TestToolSecurityFlows({ flows, currentFlow, onChange }: TestToolSecurityFlowsProps) {
  const [flow, setFlow] = useState<string | null>(null);
  const [id, setId] = useState<string>('');

  useEffect(() => {
    let newFlow = flow;
    if (flow === null) {
      [newFlow] = Object.keys(flows);
    }
    if (currentFlow && newFlow !== currentFlow) {
      newFlow = currentFlow;
    }
    if (newFlow !== flow) {
      // Only update if there's an actual change
      setFlow(newFlow);
    }
  }, [currentFlow, flows, flow]);

  useEffect(() => {
    const id = uniqueId('security-flow-select');
    setId(id);
  }, []);

  const handleFlowChange = (event: ChangeEvent<HTMLSelectElement>) => {
    const selectedFlow = event.target.value;
    setFlow(selectedFlow); // Update state with selected value
    if (onChange && typeof onChange === 'function') {
      onChange(selectedFlow);
    }
  };

  return (
    <div className="securityFlowChooser">
      {flow && (
        <Select value={flow} onChange={handleFlowChange} id={id} hideLabel>
          {Object.keys(flows).map((currentflow) => (
            <SelectItem key={currentflow} value={currentflow} text={currentflow} />
          ))}
        </Select>
      )}
    </div>
  );
}

export default TestToolSecurityFlows;
