// Create a navigation function that can be easily mocked in tests
export const navigateTo = (url: string): void => {
  window.location.assign(url);
};

/**
 * Validates if a URL is safe to use with window.location
 * Only allows https: protocol for security
 * @param urlString The URL string to validate
 * @returns true if the URL is valid and uses https protocol, false otherwise
 */
export const isUrlSafe = (urlString: string): boolean => {
  if (!urlString || urlString.trim() === '') {
    return false;
  }

  try {
    const url = new URL(urlString);

    return url.protocol === 'https:';
  } catch {
    // If URL parsing fails (malformed URL), return false
    return false;
  }
};

/**
 * Safely navigates to a URL after validating it
 * Only allows https: protocol for security
 * @param urlString The URL string to navigate to
 * @returns true if navigation was attempted, false if URL was invalid/unsafe
 */
export const safeNavigate = (urlString: string): boolean => {
  if (!isUrlSafe(urlString)) {
    return false;
  }

  try {
    const url = new URL(urlString);
    navigateTo(url.href);
    return true;
  } catch {
    console.warn('Error navigating to URL:', urlString);
    return false;
  }
};
