import { API } from './common-interfaces/common-interfaces.ts';

const APITypes = {
  graphql: 'GraphQL',
  wsdl: 'SOAP',
  'wsdl-to-rest': 'REST',
  rest: 'REST',
  asyncapi: 'AsyncAPI',
  odata: 'OData',
} as const;

type APITypesKey = keyof typeof APITypes;

function getAPIType(api: API): string {
  if (api.asyncapi) {
    return APITypes.asyncapi;
  }
  const type = api['x-ibm-configuration'] && api['x-ibm-configuration'].type;
  if (type) {
    // normalize to lowercase to match object keys
    const key = type.toLowerCase() as APITypesKey;
    if (key in APITypes) {
      return APITypes[key];
    }
    return type; 
  }

  return APITypes.rest;
}

export { APITypes, getAPIType };
