import { Button } from '@carbon/react';
import React, { useMemo, useState, ReactElement } from 'react';
import { useTranslation } from 'react-i18next';
import Invoker from '../utils/invoker';
import { getOauthErrorMessage } from '../utils/error-message-handler';

interface AuthToken {
  access_token: string;
  refresh_token?: string;
  [key: string]: any;
};

interface AuthError {
  highlightedText?: {
    __html: string;
  };
  [key: string]: any;
};

interface Identification {
  clientID: string;
  clientSecret: string;
  [key: string]: any;
};

interface Flags {
  selectedRefreshUrl?: string;
  selectedTokenUrl?: string;
  [key: string]: any;
};

interface Config {
  identification: Identification;
  flags: Flags;
  [key: string]: any;
};

interface TestToolRefreshTokenProps {
  config: Config;
  onClick: Function;
};

function TestToolRefreshToken({ config, onClick }: TestToolRefreshTokenProps): ReactElement {
  const [authToken, setAuthToken] = useState<AuthToken>({ access_token: '' });
  const [authError, setAuthError] = useState<AuthError>({});
  const invoker = useMemo(() => new Invoker(), []);
  const { t } = useTranslation();

  const refreshToken = async (): Promise<void> => {
    const { identification } = config;
    const oauthRefreshUrl = config.flags.selectedRefreshUrl ? config.flags.selectedRefreshUrl : config.flags.selectedTokenUrl;
    const token = { ...authToken };
    const error: AuthError = {};
    try {
      const response = await invoker.refreshToken(oauthRefreshUrl, token, identification.clientID, identification.clientSecret);

      setAuthError(error);
      Object.keys(response).forEach((key) => {
        token[key] = response[key];
      });
    } catch (err: any) {
      console.error(err?.stack);
      const errorMsg = await getOauthErrorMessage(err, t);
      setAuthError(errorMsg);
    } finally {
      setAuthToken(token);
      if (onClick && typeof onClick === 'function') {
        onClick({ authToken: token, authError: error });
      }
    }
  };

  return (
    <div className="refreshToken">
      <Button className="refreshTokenButton" id="refreshTokenButton" onClick={refreshToken}>
        {t('explorer_refresh_token')}
      </Button>
      {authError && authError.highlightedText && (
        <div className="authError">
          <pre>
            <code className="boundedSection hljs oauthError" dangerouslySetInnerHTML={authError.highlightedText} />
          </pre>
        </div>
      )}
    </div>
  );
}

export default TestToolRefreshToken;
