import React from 'react';
import { useTranslation } from 'react-i18next';
import { DataTable } from '@carbon/react';
import { useApi } from '../contexts/ApiHandler/index.tsx';

const { TableContainer, Table, TableHead, TableHeader, TableBody, TableRow, TableCell } = DataTable;

function ODataEntitySetOverview({ entitySetName }) {
  const { apiHandler } = useApi();
  const { t } = useTranslation();

  // Get entity sets and find the one matching the name
  const entitySets = apiHandler.getEntitySets ? apiHandler.getEntitySets() : [];
  const entitySet = entitySets.find((es) => es.name === entitySetName);

  // Get operations for this entity set
  const operations = apiHandler.getOperations ? apiHandler.getOperations() : [];
  const entitySetOperations = operations.filter((op) =>
    op.boundTo === entitySet?.entityType || !op.boundTo
  );

  if (!entitySet) {
    return (
      <div className="odata-entity-set-overview">
        <h2>{t('error')}</h2>
        <p>{t('entity_set_not_found', { name: entitySetName })}</p>
      </div>
    );
  }

  return (
    <div className="odata-entity-set-overview">
      <h2>{entitySet.name}</h2>
      {entitySet.description && (
        <p className="entity-set-description">{entitySet.description}</p>
      )}
      
      <div className="entity-set-details">
        <h3>{t('odata_properties')}</h3>
        <DataTable rows={[]} headers={[]}>
          {() => (
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableHeader>{t('name')}</TableHeader>
                    <TableHeader>{t('type')}</TableHeader>
                    <TableHeader>{t('nullable')}</TableHeader>
                    <TableHeader>{t('key')}</TableHeader>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {entitySet.properties && entitySet.properties.map((prop) => (
                    <TableRow key={prop.name}>
                      <TableCell>{prop.name}</TableCell>
                      <TableCell>{prop.type}</TableCell>
                      <TableCell>{prop.nullable ? t('yes') : t('no')}</TableCell>
                      <TableCell>{prop.key ? '🔑' : ''}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </DataTable>
      </div>

      {entitySet.navigationProperties && entitySet.navigationProperties.length > 0 && (
        <div className="entity-set-navigation">
          <h3>{t('odata_navigation_properties')}</h3>
          <DataTable rows={[]} headers={[]}>
            {() => (
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableHeader>{t('name')}</TableHeader>
                      <TableHeader>{t('type')}</TableHeader>
                      <TableHeader>{t('relationship')}</TableHeader>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {entitySet.navigationProperties.map((navProp) => (
                      <TableRow key={navProp.name}>
                        <TableCell>{navProp.name}</TableCell>
                        <TableCell>{navProp.type}</TableCell>
                        <TableCell>{navProp.relationship}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
          </DataTable>
        </div>
      )}

      {entitySetOperations.length > 0 && (
        <div className="entity-set-operations">
          <h3>{t('odata_operations')}</h3>
          <DataTable rows={[]} headers={[]}>
            {() => (
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableHeader>{t('name')}</TableHeader>
                      <TableHeader>{t('type')}</TableHeader>
                      <TableHeader>{t('return_type')}</TableHeader>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {entitySetOperations.map((op) => (
                      <TableRow key={op.name}>
                        <TableCell>{op.name}</TableCell>
                        <TableCell>
                          <span className={`operation-badge operation-${op.type}`}>
                            {op.type}
                          </span>
                        </TableCell>
                        <TableCell>{op.returnType}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
          </DataTable>
        </div>
      )}
    </div>
  );
}

export default ODataEntitySetOverview;