import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import classNames from 'classnames';
import { DataTable } from '@carbon/react';
import { sortBy } from 'lodash';
import { cleanUpKey } from '../utils/common';

const { TableContainer, Table, TableHead, TableHeader, TableBody, TableRow, TableExpandHeader, TableExpandRow, TableExpandedRow, TableCell } = DataTable;

const EntitySetsBody = ({ entitySets }) => {
  const { t } = useTranslation();
  const [expandedIndex, updateExpandedIndex] = useState(-1);
  const toggleRow = (rowIndex) => () => updateExpandedIndex(rowIndex === expandedIndex ? -1 : rowIndex);

  return (
    entitySets &&
    entitySets.length > 0 &&
    entitySets.map((entitySet, index) => {
      const entitySetName = entitySet.name;
      const isExpanded = expandedIndex === index;
      return (
        <React.Fragment key={entitySetName}>
          <TableExpandRow
            key={entitySetName}
            className={classNames('entitySetRow', `entityset-${cleanUpKey(entitySetName)}`)}
            isExpanded={isExpanded}
            ariaLabel="toggleCurrentRow"
            expandIconDescription="toggleCurrentRow"
            onExpand={toggleRow(index)}
            data-testid={`entitySetRow-${index}`}
          >
            <TableCell className="entitySetName">{entitySetName}</TableCell>
            <TableCell className="entitySetType">{entitySet.entityType}</TableCell>
            <TableCell className="entitySetProperties">{entitySet.properties?.length || 0}</TableCell>
          </TableExpandRow>
          {isExpanded && (
            <TableExpandedRow className="expandrow" colSpan={12} data-testid={`entitySetRow-expanded-${index}`}>
              <div className="tablecell odata-entityset-details">
                <div className="odata-section">
                  <h4>{t('odata_properties')}</h4>
                  <table className="odata-properties-table">
                    <thead>
                      <tr>
                        <th>{t('name')}</th>
                        <th>{t('type')}</th>
                        <th>{t('nullable')}</th>
                        <th>{t('key')}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {entitySet.properties?.map((prop) => (
                        <tr key={prop.name}>
                          <td className="property-name">{prop.name}</td>
                          <td className="property-type">{prop.type}</td>
                          <td className="property-nullable">{prop.nullable ? t('yes') : t('no')}</td>
                          <td className="property-key">{prop.key ? '🔑' : ''}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                
                {entitySet.navigationProperties && entitySet.navigationProperties.length > 0 && (
                  <div className="odata-section">
                    <h4>{t('odata_navigation_properties')}</h4>
                    <table className="odata-navigation-table">
                      <thead>
                        <tr>
                          <th>{t('name')}</th>
                          <th>{t('type')}</th>
                          <th>{t('relationship')}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {entitySet.navigationProperties.map((navProp) => (
                          <tr key={navProp.name}>
                            <td className="nav-name">{navProp.name}</td>
                            <td className="nav-type">{navProp.type}</td>
                            <td className="nav-relationship">{navProp.relationship}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </TableExpandedRow>
          )}
        </React.Fragment>
      );
    })
  );
};

function EntitySetsList({ api, apiHandler }) {
  const { t } = useTranslation();
  const [entitySets, setEntitySets] = useState([]);
  
  // Update entity sets when metadata loads
  useEffect(() => {
    
    const updateEntitySets = () => {
      const sets = apiHandler.getEntitySets();
      setEntitySets(sets);
    };
    
    // Initial fetch
    updateEntitySets();
    
    // Listen for metadata loaded event
    const handleMetadataLoaded = () => {
      updateEntitySets();
    };
    
    window.addEventListener('odata-metadata-loaded', handleMetadataLoaded);
    
    return () => {
      window.removeEventListener('odata-metadata-loaded', handleMetadataLoaded);
    };
  }, [apiHandler]);
  
  const sortedEntitySets = sortBy(entitySets, [(entitySet) => entitySet.name.toLowerCase()]);

  return (
    <div
      className={classNames(
        'apiconnect-explorer',
        'entitysets-section',
        'main',
        'odata-api',
        `entitysets-${cleanUpKey(`${api.info.title}_${api.info.version}`)}`
      )}
    >
      <section className="entitySetsHeader" aria-label="entitysets-header">
        <h2 className="section-title">{t('odata_entity_sets')}</h2>
      </section>
      <section className="entitySetsBody" aria-label="entitysets-body">
        <DataTable rows={[]} headers={[]}>
          {() => (
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableExpandHeader />
                    <TableHeader>{t('name')}</TableHeader>
                    <TableHeader>{t('entity_type')}</TableHeader>
                    <TableHeader>{t('properties')}</TableHeader>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <EntitySetsBody entitySets={sortedEntitySets} />
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </DataTable>
      </section>
    </div>
  );
}

export default EntitySetsList;
