import React from 'react';
import { withTranslation } from 'react-i18next';
import { Accordion, AccordionItem } from '@carbon/react';
import { useApi } from '../contexts/ApiHandler/index.tsx';
import { useConfig } from '../contexts/config';
import Operation from './Operation.tsx';

type CallbackProps = {
  event: any;
  callbacks: any;
  operation: any;
  apps: any;
}

function Callback({ event, callbacks, operation, apps, ...others }: CallbackProps) {
  const { api }: any = useApi();
  const { options }: any = useConfig();

  operation = JSON.parse(JSON.stringify(operation));
  operation.openapi = api.openapi;

  return (
    <div className="callbacks-tab-content" {...others}>
      <div className="eventName">{event}</div>
      <Accordion>
        {Object.keys(callbacks).map((path) => {
          const [method, callback] = Object.entries(callbacks[path])[0];
          return (
            <AccordionItem className="callback-accordion" title={`${method.toUpperCase()} ${path}`} open>
              <Operation operation={callback} operationPath={path} operationMethod={method} options={options} apps={apps} isCallback />
            </AccordionItem>
          );
        })}
      </Accordion>
    </div>
  );
}

export default withTranslation()(Callback);
