import React from 'react';
import ApiExplorer from './ApiExplorer';
import { MemoryRouter, HashRouter } from 'react-router-dom';

// Light weight veneer version, add more dependencies and featues here.
function ApiExplorerApp({ options, apis, encodedApis, apps, docs }) {
    // Determine which router to use based on options
    const routerType = options?.routerType;
    let Router = MemoryRouter;
    
    if (routerType === 'hash') {
        Router = HashRouter;
    } else if (routerType && routerType !== 'memory') {
        throw new Error(
            `Unsupported router type: '${routerType}'. Available options: memory, hash`
        );
    }
    
    return (
        <Router>
            <ApiExplorer options={options} apis={apis} encodedApis={encodedApis} apps={apps} docs={docs} />
        </Router>
    );
}

export default ApiExplorerApp;