import React, { useEffect, useState, ReactElement, ChangeEvent } from 'react';
import { useTranslation } from 'react-i18next';
import { TextInput, Select, SelectItem } from '@carbon/react';

type RedirectUriValue = {
  redirectUri?: string;
  redirectUris: string[];
  scramEncryptedCreds?: string;
  [key: string]: any;
};

type TestToolRedirectUriProps = {
  value: RedirectUriValue;
  onChange?: Function;
};

function TestToolRedirectUri({ value, onChange }: TestToolRedirectUriProps): ReactElement {
  const [redirectUri, setRedirectUri] = useState<string>('');
  const { t } = useTranslation();

  useEffect(() => {
    setRedirectUri(value.redirectUri ?? '');
  }, [value.scramEncryptedCreds, value.redirectUri]);

  const handleChange = (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>): void => {
    const newRedirectUri = event.target.value;
    setRedirectUri(newRedirectUri);
    if (onChange && typeof onChange === 'function') {
      onChange({ redirectUri: newRedirectUri });
    }
  };

  const { redirectUris } = value;
  let uriSelector: ReactElement | undefined;
  let uriInput: ReactElement | undefined;

  if (redirectUris.length > 0 && redirectUris[0] !== '') {
    // need a dropdown
    uriSelector = (
      <Select onChange={handleChange} id="redirectUri-select" defaultValue={redirectUris[0]} hideLabel>
        {redirectUris.map((param) => (
          <SelectItem key={param} value={param} text={param} />
        ))}
        <SelectItem key="" value="" text={t('other')} />
      </Select>
    );
  }
  if (redirectUris[0] === '' || redirectUris.indexOf(redirectUri) === -1) {
    uriInput = (
      <TextInput
        className="redirectUriField"
        type="input"
        hideLabel
        labelText={t('explorer_redirect_uri')}
        id="redirectUriField"
        value={redirectUri}
        onChange={handleChange}
      />
    );
  }

  return (
    <div className="redirectUri">
      <div className="labelText">{t('explorer_redirect_uri')}</div>
      <div className="securityHeader">
        <div className="requiredHighlight parameterIn">{t('required')}</div>
      </div>
      {uriSelector}
      {uriInput}
    </div>
  );
}

export default TestToolRedirectUri;
