import React, { useState, ChangeEvent } from 'react';
import { Checkbox } from '@carbon/react';
import { useTranslation } from 'react-i18next';

type ScopesMap = {
  [key: string]: boolean;
};

type TestToolScopesProps = {
  scopes?: string[];
  // eslint-disable-next-line
  onChange?: (selectedScopes: ScopesMap) => void;
};

function TestToolScopes({ scopes, onChange }: TestToolScopesProps): React.ReactElement {
  const { t } = useTranslation();
  const [selectedScopes, setSelectedScopes] = useState<ScopesMap>({});

  const handleScopeChange = (scope: string, event: ChangeEvent<HTMLInputElement>): void => {
    const newScopes = { ...selectedScopes };
    newScopes[scope] = event.target.checked;
    if (onChange && typeof onChange === 'function') {
      onChange(newScopes);
    }
    setSelectedScopes(newScopes);
  };

  const scopeStates: ScopesMap = {};
  if (scopes) {
    for (let i = 0; i < scopes.length; i += 1) {
      scopeStates[scopes[i]] = false;
    }
  }

  return (
    <div className="scopesChooser">
      <div className="labelText">{t('explorer_scopes')}</div>
      <div className="securityHeader">
        <div className="requiredHighlight parameterIn">{t('required')}</div>
      </div>
      {Object.keys(scopeStates).map((scope) => (
        <Checkbox key={scope} labelText={scope} id={scope} onChange={(e) => handleScopeChange(scope, e)} />
      ))}
    </div>
  );
}

export default TestToolScopes;
