import React, { useMemo, useCallback, useEffect, useState } from 'react';
import { Marked } from 'marked';
import { gfmHeadingId } from 'marked-gfm-heading-id';
import { mangle } from 'marked-mangle';
import DOMPurify from 'dompurify';
import classNames from 'classnames';
import MarkupTypes from '../utils/MarkupTypes.ts';

type MarkdownProps = {
  data: string,
  className: string,
  markupType: MarkupTypes
}

const Markdown = ({ data, className, markupType, ...otherProps }: MarkdownProps) => {
  const marked = useMemo(() => new Marked(), []);
  marked.use(mangle());
  const options = {
    prefix: ''
  };

  marked.use(gfmHeadingId(options));
  const parseData = useCallback(
    (data: any, type: string) => {
      if (!data) {
        return;
      }
      if (type === MarkupTypes.markdown) {
        // Use marked for swagger 1.0 and 2.0
        return DOMPurify.sanitize(marked.parse(data) as string);
      }
      // Use markdown-it (implements commonmark spec)
      // eslint-disable-next-line global-require
      const md = require('markdown-it')('commonmark');
      return DOMPurify.sanitize(md.render(data));
    },
    [marked]
  );
  const [convertedData, updateConvertedData] = useState(() => parseData(data, markupType));

  useEffect(() => {
    updateConvertedData(parseData(data, markupType));
  }, [data, markupType, parseData]);

  return <div className={classNames('markdown', className)} data-testid="markdown" dangerouslySetInnerHTML={{ __html: convertedData as string }} {...otherProps} />;
}

export default Markdown;
