import React, { useState, useEffect, useContext } from 'react';
import defaultOptions from './defaultOptions';
import { b64DecodeUnicode } from '../../utils/common';
import { has } from 'lodash';

const ConfigContext = React.createContext({});

const getApis = (config) => {
  if (config.encodedApis) {
    return config.encodedApis.map((encodedApi) => JSON.parse(b64DecodeUnicode(encodedApi)));
  } else {
    return config.apis;
  }
};

const getConfig = (options, apps, apis, encodedApis, docs) => {
  let config = typeof window !== 'undefined' && window.apiConnectExplorer || {};

  if (typeof window !== 'undefined') {
    if (has(window, 'drupalSettings.api.explorer')) {
      config = window.drupalSettings.api.explorer;
    } else if (has(window, 'Drupal.settings.api.explorer')) {
      // support for Drupal7 style Drupal.settings
      config = window.Drupal.settings.api.explorer;
    }
  }

  // Use props instead if provided
  config.options = options ? options : config.options;
  config.apps = apps ? apps : config.apps;
  config.apis = apis || encodedApis ? getApis({ apis, encodedApis }) : getApis(config);
  config.docs = docs ? docs : config.docs;
  config.constants = {
    HASH_ROUTER: 'hash',
    MEMORY_ROUTER: 'memory'
  }
  config.options = Object.assign({}, defaultOptions, config.options);

  return config
}

const ConfigProvider = ({ options, apps, apis, encodedApis, docs, children }) => {
  const [configState, updateConfig] = useState(() => getConfig(options, apps, apis, encodedApis, docs));

  const explorerUpdateListener = () => {
    updateConfig(Object.assign({}, getConfig(options, apps, apis, encodedApis, docs)));
  };

  useEffect(() => {
    updateConfig(getConfig(options, apps, apis, encodedApis, docs));
  }, [options, apps, apis, encodedApis, docs])

  useEffect(() => {
    window.addEventListener('apiConnectExplorerUpdate', explorerUpdateListener);
    return () => {
      window.removeEventListener('apiConnectExplorerUpdate', explorerUpdateListener);
    }
  }, []);

  return (
    <ConfigContext.Provider value={configState} >
      {children}
    </ConfigContext.Provider>
  );
};

const useConfig = () => useContext(ConfigContext);

export default ConfigProvider
export {
  useConfig,
  ConfigContext
}
