import React from 'react';
import { Select, SelectItem } from '@carbon/react';
import { useTranslation } from 'react-i18next';
import DOMPurify from 'dompurify';
import { useApi } from '../contexts/ApiHandler/index.tsx';

type EndpointSelectorProps = {
  endpoints: any[];
  opPath: string;
  onChange: (evt: React.ChangeEvent<HTMLSelectElement>, index?: number) => void;
  id: string;
  endpoint: string;
}

const EndpointSelector = ({endpoints, opPath, id, endpoint,
  onChange = () => {
    console.warn('EndpointSelector onChange not set')
  }
}: EndpointSelectorProps) => {
  const { t } = useTranslation();
  const { apiHandler }: any = useApi();

  let operationEndpoints;

  if (endpoints && endpoints.length > 1) {
    operationEndpoints = (
      <Select data-testid={id} onChange={onChange} id={id} value={endpoint || endpoints[0].url} hideLabel>
        {endpoints.map((param) => {
          const paramTypesText = param.types ? `${DOMPurify.sanitize(param.types)}: ` : '';
          // eslint-disable-next-line no-unsafe-optional-chaining
          const sanitizedUrl = DOMPurify.sanitize(param.url, { ALLOWED_TAGS: [], ALLOWED_ATTR: [] });
          const fullUrl = apiHandler?.buildFullUrl(sanitizedUrl, opPath);
          return <SelectItem key={sanitizedUrl} value={sanitizedUrl} text={paramTypesText + fullUrl} />;
        })}
      </Select>
    );
  } else if (endpoints && endpoints.length === 1 && endpoints[0].url) {
    const endpointTypesText = endpoints[0].types ? `${DOMPurify.sanitize(endpoints[0].types)}: ` : '';
    const sanitizedUrl = DOMPurify.sanitize(endpoints[0].url, { ALLOWED_TAGS: [], ALLOWED_ATTR: [] });
    operationEndpoints = (
      <div className="apiEndpoint" key={sanitizedUrl}>
        {endpointTypesText && <div className="apiEndpointType">{endpointTypesText}</div>}
        <div className="apiEndpointUrl">{apiHandler?.buildFullUrl(sanitizedUrl, opPath)}</div>
      </div>
    );
  } else {
    operationEndpoints = <div>{t('no_endpoint')}</div>;
  }

  return <div className="endpointDisplay">{operationEndpoints}</div>;
}

export default EndpointSelector;
