import React from 'react';
import { Loading, useTheme } from '@carbon/react';
import { JSONTree } from 'react-json-tree';
import DOMPurify from 'dompurify';
import MarkdownIt from 'markdown-it';

const md = new MarkdownIt();

function Load() {
  return <Loading small withOverlay={false} data-testid="json-loading-icon" />;
}

type ViewableJSONDisplayProps = {
  content: object | any[], // JSON Content to be displayed
  jsonName?: string | null // Name to be displayed at top of JSON Viewer
}

// Label renderer function extracted outside component
function labelRenderer(keyPath: [string]) {
  const [label] = keyPath;
  if (keyPath.length === 1 && label === 'root') {
    return <span>{}</span>;
  }
  return <span>{typeof label === 'string' ? `"${label}"` : String(label)}<span className='jsonDataKeyColon'>:</span></span>;
}

// Always expand nodes initially
const shouldExpandNodeInitially = () => true;


const ViewableJSONDisplay = ({ content, jsonName = null }: ViewableJSONDisplayProps) => {
  // Renders markdown only for "description" keys
  const valueRenderer = (raw: any, value: string, keyPath: string | string[]) => {
    const path = Array.isArray(keyPath) ? keyPath : [keyPath];
    const isDescription = path[path.length - 1] === 'description';

    if (isDescription && typeof value === 'string') {
      const markdownInput = value;
      const renderedHtml = md.render(markdownInput);
      const safeHtml = DOMPurify.sanitize(renderedHtml);
      return <div style={{ padding: '0.25rem 0' }} className="markdown-description" dangerouslySetInnerHTML={{ __html: safeHtml }} />;
    }

    return <span>{typeof value === 'string' ? `"${value}"` : String(value)}</span>;
  };

  const { theme } = useTheme();
  const explorerTheme = {
    base00: 'unset', // background
    base01: '#f4f4f4',
    base02: '#e0e0e0',
    base03: '#6f6f6f', // helper text (gray)
    base04: '#525252',
    base05: '#161616',
    base06: '#161616',
    base07: '#161616', // TEXT_COLOR
    base08: '#da1e28', // NULL_COLOR, UNDEFINED_COLOR, FUNCTION_COLOR, SYMBOL_COLOR
    base09: '#4646e6', // numbers / booleans (blue-purple)
    base0A: '#0f62fe',
    base0B: '#008000', // STRING_COLOR, DATE_COLOR, ITEM_STRING_COLOR (green)
    base0C: '#0043ce',
    base0D: '#660066', // keys (purple)
    base0E: '#6f42c1',
    base0F: '#8a3ffc',
  };

  const explorerDarkTheme = {
    base00: 'unset', // background
    base01: '#f4f4f4',
    base02: '#e0e0e0',
    base03: '#c6c6c6', // helper text (gray)
    base04: '#525252',
    base05: '#ffffff', // text color
    base06: '#f4f4f4',
    base07: '#f4f4f4',
    base08: '#ff8389', // errors (red)
    base09: '#70a3ff', // numbers / booleans (blue)
    base0A: '#b0cbff', // strings (blue)
    base0B: '#71ce8c', // strings (green)
    base0C: '#81aaff', // strings (deep blue)
    base0D: '#ccacfd', // keys (purple - main)
    base0E: '#c098fd', // keys (purple)
    base0F: '#c098fd'  // keys (purple)
  };

 const jsonTreeTheme =  (theme === 'g90' || theme === 'g100') ? explorerDarkTheme : explorerTheme;

  return (
    <>
      {!content && <Load />}
      {content && (
        <div className='jsonDataTreeDisplay' data-testid="json-data">
          {jsonName && (
            <span data-testid="json-name" style={{ display: 'none' }}>
              {jsonName}
            </span>
          )}
          <JSONTree
            data={content}
            theme={jsonTreeTheme}
            valueRenderer={valueRenderer}
            hideRoot={false}
            labelRenderer={labelRenderer}
            shouldExpandNodeInitially={shouldExpandNodeInitially}
          />
        </div>
      )}
    </>
  );
}

export default ViewableJSONDisplay;
