import React, { RefObject } from 'react';
import { CopyButton } from '@carbon/react';
import classNames from 'classnames';
import { useTranslation } from 'react-i18next';
import { handleKeyDown } from '../utils/common';

// Check if copy command is supported
let copyEnabled = false;
if (typeof document !== 'undefined' && document.queryCommandSupported) {
  copyEnabled = document.queryCommandSupported('copy');
}

type CopierProps = {
  className?: string;
  renderStyle?: string;
  buttonText?: string;
  element?: string;
  copierRef?: RefObject<HTMLElement> | RefObject<null>;
}

const copyTextCurry = (element?: string, copierRef?: RefObject<HTMLElement> | RefObject<null>) => (): void => {
  const elementNode = element && document.querySelector(element) 
    ? document.querySelector(element) 
    : copierRef?.current;
    
  if (!elementNode) {
    // Can't proceed
    return;
  }
  // select and copy
  const range = document.createRange();
  range.selectNodeContents(elementNode);
  const sel = window.getSelection();
  if (sel) {
    sel.removeAllRanges();
    sel.addRange(range);

    // we've at least selected the text... but
    if (copyEnabled) {
      // we can also copy straight to the clipboard
      document.execCommand('copy');
      sel.removeAllRanges();
    }
  }
};

const Copier = ({ 
  className = '', 
  renderStyle = '', 
  buttonText, 
  element, 
  copierRef 
}: CopierProps): React.ReactElement => {
  const { t } = useTranslation();
  const copyText = copyTextCurry(element, copierRef);

  if (renderStyle === 'button') {
    return (
      <span className={classNames('apiconnect-copier', className)}>
        <button 
          type="button" 
          tabIndex={0} 
          className="cds--btn cds--btn--secondary" 
          onClick={copyText} 
          onKeyDown={handleKeyDown(copyText)}
        >
          {buttonText}
        </button>
      </span>
    );
  }
  
  return (
    <CopyButton 
      autoAlign
      onClick={copyText} 
      feedback={t('copied_to_clipboard')} 
      iconDescription={t('copy_to_clipboard')} 
      data-testid="copy-button" 
    />
  );
}

export default Copier;
