import RdKafkaCodeSnippet from './RdKafkaCodeSnippet.ts';

export default class KafkacatKafkaCodeSnippet extends RdKafkaCodeSnippet {
  getBootstrapServers() {
    return this.apiHandler
      .getEndpoints()
      .map(({ url }: { url: string }) => url)
      .join(',');
  }
}
