import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import classNames from 'classnames';
import { DataTable, Tag } from '@carbon/react';
import { sortBy } from 'lodash';
import { cleanUpKey } from '../utils/common';
import Markdown from './Markdown.tsx';

const { TableContainer, Table, TableHead, TableHeader, TableBody, TableRow, TableExpandHeader, TableExpandRow, TableExpandedRow, TableCell } = DataTable;

const OperationsBody = ({ operations, markupType }) => {
  const { t } = useTranslation();
  const [expandedIndex, updateExpandedIndex] = useState(-1);
  const toggleRow = (rowIndex) => () => updateExpandedIndex(rowIndex === expandedIndex ? -1 : rowIndex);

  return (
    operations &&
    operations.length > 0 &&
    operations.map((operation, index) => {
      const operationName = operation.name;
      const isExpanded = expandedIndex === index;
      const operationType = operation.type; // 'function' or 'action'
      
      return (
        <React.Fragment key={operationName}>
          <TableExpandRow
            key={operationName}
            className={classNames('operationRow', `operation-${cleanUpKey(operationName)}`)}
            isExpanded={isExpanded}
            ariaLabel="toggleCurrentRow"
            expandIconDescription="toggleCurrentRow"
            onExpand={toggleRow(index)}
            data-testid={`operationRow-${index}`}
          >
            <TableCell className="operationName">{operationName}</TableCell>
            <TableCell className="operationType">
              <Tag type={operationType === 'function' ? 'blue' : 'purple'} size="sm">
                {operationType}
              </Tag>
            </TableCell>
            <TableCell className="operationReturn">{operation.returnType || 'void'}</TableCell>
          </TableExpandRow>
          {isExpanded && (
            <TableExpandedRow className="expandrow" colSpan={12} data-testid={`operationRow-expanded-${index}`}>
              <div className="tablecell odata-operation-details">
                {operation.description && (
                  <div className="odata-section">
                    <h4>{t('description')}</h4>
                    <Markdown data={operation.description} markupType={markupType} />
                  </div>
                )}
                
                {operation.parameters && operation.parameters.length > 0 && (
                  <div className="odata-section">
                    <h4>{t('parameters')}</h4>
                    <table className="odata-parameters-table">
                      <thead>
                        <tr>
                          <th>{t('name')}</th>
                          <th>{t('type')}</th>
                          <th>{t('nullable')}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {operation.parameters.map((param) => (
                          <tr key={param.name}>
                            <td className="param-name">{param.name}</td>
                            <td className="param-type">{param.type}</td>
                            <td className="param-nullable">{param.nullable ? t('yes') : t('no')}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
                
                {operation.boundTo && (
                  <div className="odata-section">
                    <h4>{t('bound_to')}</h4>
                    <p className="bound-entity">{operation.boundTo}</p>
                  </div>
                )}
              </div>
            </TableExpandedRow>
          )}
        </React.Fragment>
      );
    })
  );
};

function OperationsList({ api, apiHandler }) {
  const { t } = useTranslation();
  const [operations, setOperations] = useState([]);
  const markupType = apiHandler.getMarkupType();
  
  // Update operations when metadata loads
  useEffect(() => {
    
    const updateOperations = () => {
      const ops = apiHandler.getOperations();
      setOperations(ops);
    };
    
    // Initial fetch
    updateOperations();
    
    // Listen for metadata loaded event
    const handleMetadataLoaded = () => {
      updateOperations();
    };
    
    window.addEventListener('odata-metadata-loaded', handleMetadataLoaded);
    
    return () => {
      window.removeEventListener('odata-metadata-loaded', handleMetadataLoaded);
    };
  }, [apiHandler]);
  
  const sortedOperations = sortBy(operations, [(operation) => operation.name.toLowerCase()]);

  return (
    <div
      className={classNames(
        'apiconnect-explorer',
        'operations-section',
        'main',
        'odata-api',
        `operations-${cleanUpKey(`${api.info.title}_${api.info.version}`)}`
      )}
    >
      <section className="operationsHeader" aria-label="operations-header">
        <h2 className="section-title">{t('odata_operations')}</h2>
      </section>
      <section className="operationsBody" aria-label="operations-body">
        <DataTable rows={[]} headers={[]}>
          {() => (
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableExpandHeader />
                    <TableHeader>{t('name')}</TableHeader>
                    <TableHeader>{t('type')}</TableHeader>
                    <TableHeader>{t('return_type')}</TableHeader>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <OperationsBody operations={sortedOperations} markupType={markupType} />
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </DataTable>
      </section>
    </div>
  );
}

export default OperationsList;
