import { cleanUpKey } from 'utils/common';

const apiPath = (api) => {
  if (api) {
    return cleanUpKey(`${api.info.title}_${api.info.version}`);
  }
};

const eventPath = (api, channelName, where) => {
  let path = '';
  if (api) path += `/${apiPath(api)}`;
  if (channelName) path += `/${encodeURIComponent(channelName)}`;
  if (where) path += `/${where}`;
  return path;
};

const decodeChannelName = (channel) => decodeURIComponent(channel);

const getCurrentItemFromPath = (pathname) => {
  const splitPath = pathname.split('/');
  let selectedItem = '';
  
  // Check for standalone documentation first (/documentation/...)
  if (splitPath[1] === 'documentation') {
    selectedItem = `${splitPath[2]}_${splitPath[splitPath.length - 1]}`;
    return selectedItem;
  }

  // Find API name index (contains underscore, like "API_1")
  const apiIndex = splitPath.findIndex(part => part.includes('_'));

  if (apiIndex === -1) {
    return selectedItem;
  }
  
  // Use apiIndex as base for all checks
  const nextPart = splitPath[apiIndex + 1];
  const thirdPart = splitPath[apiIndex + 2];
  
  // api checks
  switch (nextPart) {
    case 'overview':
      selectedItem = 'overview';
      break;
    case 'operation':
      selectedItem = `${decodeURIComponent(splitPath[apiIndex + 2])}_${splitPath[apiIndex + 3]}`;
      break;
    case 'definitions':
      selectedItem = 'definitions';
      break;
    case 'documentation':
      selectedItem = `${splitPath[apiIndex]}_${nextPart}_${splitPath[apiIndex + 2]}_${splitPath[splitPath.length - 1]}`;
      break;
    case 'webhook':
      selectedItem = `${splitPath[apiIndex]}_${nextPart}_${splitPath[splitPath.length - 1]}`;
      break;
    default:
      break;
  }
  
  // channel checks
  switch (thirdPart) {
    case 'overview':
      selectedItem = `${decodeURIComponent(nextPart)}_overview`;
      break;
    case 'operation':
      selectedItem = `${decodeURIComponent(nextPart)}_${decodeURIComponent(splitPath[apiIndex + 3])}`;
      break;
    case 'publish':
    case 'subscribe':
      selectedItem = `${decodeURIComponent(nextPart)}_data`;
      break;
    default:
      break;
  }
  
  return selectedItem;
};

const getApi = (apis, apiName) => apis.find((api) => apiPath(api) === apiName);

export { apiPath, getCurrentItemFromPath, getApi, eventPath, decodeChannelName };
