import React, { useState, ReactElement } from 'react';
import { Loading, Tabs, Tab, Button, TabList, TabPanels, TabPanel } from '@carbon/react';
import classNames from 'classnames';
import { CheckmarkFilled, InformationFilled, Misuse, WarningFilled, View, ViewOff } from '@carbon/react/icons';
import { get, cloneDeep } from 'lodash';
import { useTranslation } from 'react-i18next';
import CodeViewer from './CodeViewer';
import { cleanUpKey } from '../utils/common';
import Copier from './Copier';
import { getBidiAlignLogical } from '../utils/getDirectionalAlign';

type InvokeResponseHeaders = {
  [key: string]: string;
};

type InvokeResponseRequest = {
  method: string;
  url: string;
  headers: InvokeResponseHeaders;
  headersAsString: string;
};

type InvokeResponse = {
  statusCode?: number;
  statusText?: string;
  statusInfo?: string;
  request: InvokeResponseRequest;
  headers: InvokeResponseHeaders;
  headersAsString?: string;
  responseDataString?: string;
  isFileDownload?: boolean;
};

type SecurityFlags = {
  clientSecretName?: string;
  clientSecretLocation?: string;
};

type Security = {
  flags?: SecurityFlags;
};

type TestToolResponseProps = {
  invokeResponse: InvokeResponse;
  responseBody?: string;
  contentFormat?: string;
  mtlsEnabled?: boolean;
  isInvoking?: boolean;
  security?: Security;
};

function TestToolResponse({ invokeResponse, responseBody, contentFormat, mtlsEnabled, security }: TestToolResponseProps): ReactElement {
  const [showHidden, setShowHidden] = useState<boolean>(false);
  const [hasConfidential, setHasConfidential] = useState<boolean>(false);
  const { t } = useTranslation();


  
  let filteredUrl = invokeResponse?.request?.url;
  let processedInvokeResponse = invokeResponse;

  if (!showHidden) {
    const headersToHide = ['x-ibm-client-secret', 'secret', 'password'];
    const queriesToHide = ['password', 'client_secret'];
    if (security?.flags?.clientSecretName && security.flags.clientSecretName !== '') {
      if (security?.flags?.clientSecretLocation === 'query') {
        queriesToHide.push(security.flags.clientSecretName);
      } else if (security?.flags?.clientSecretLocation === 'header') {
        headersToHide.push(security.flags.clientSecretName);
      }
    }
    processedInvokeResponse = cloneDeep(invokeResponse);

    let keysToChange: Set<string> = new Set();
    if (get(processedInvokeResponse, `request.headers`)) {
      const headerKeys = Object.keys(processedInvokeResponse.request.headers);

      headersToHide.forEach((header) => {
        const filteredArr = headerKeys.filter((item) => item.toLowerCase().includes(header?.toLowerCase()));
        keysToChange = new Set([...Array.from(keysToChange), ...filteredArr]);
      });
    }

    keysToChange.forEach((header) => {
      if (get(processedInvokeResponse, `request.headers[${header}]`)) {
        processedInvokeResponse.request.headers[header] = '*********';
        // Matches from <header>: to \n
        processedInvokeResponse.request.headersAsString = processedInvokeResponse.request.headersAsString.replace(
          new RegExp(`${header}: (?:(?!\\n).)*`), 
          `${header}: =************`
        );
        if (!hasConfidential) {
          setHasConfidential(true);
        }
      }
    });

    if (get(processedInvokeResponse, `request.headers.Authorization`)) {
      const original = processedInvokeResponse.request.headers.Authorization;
      processedInvokeResponse.request.headers.Authorization = processedInvokeResponse.request.headers.Authorization.replace(/Bearer [^\s]*/, 'Bearer ************');
      processedInvokeResponse.request.headersAsString = processedInvokeResponse.request.headersAsString.replace(/Bearer [^\s]*/, 'Bearer ************');
      if (original !== processedInvokeResponse.request.headers.Authorization && !hasConfidential) {
        setHasConfidential(true);
      }
    }
    if (get(processedInvokeResponse, 'request.url')) {
      const original = processedInvokeResponse.request.url;
      queriesToHide.forEach((query) => {
        filteredUrl = processedInvokeResponse.request.url.replace(new RegExp(`${query}=[^&]*`), `${query}=************`);
      });
      if (original !== filteredUrl && !hasConfidential) {
        setHasConfidential(true);
      }
    }
  }

  const corsMsg = mtlsEnabled ? t('explorer_cors_mtls') : t('explorer_cors');

  return (
    <div className="testToolResult" data-testid="testtool-result">
      <div className="testToolSection testToolRequest">
        <h3 className="labelText">
          {t('request')}
        </h3>
        <div data-testid="testRequestBody" className={classNames('testRequestBody', 'cds--snippet', 'cds--snippet--multi')}>
          {typeof processedInvokeResponse.statusCode === 'undefined' && <Loading data-testid="loading-icon" className="invoking" small withOverlay={false} />}
          {typeof processedInvokeResponse.statusCode !== 'undefined' && (
            <div className={classNames('body', 'cds--snippet-container')}>
              <div>
                <pre>
                  <code className={classNames('boundedSection testRequestContent')}>
                    <div className="requestDetails requestUrl">
                      {processedInvokeResponse.request.method.toUpperCase()} {filteredUrl}
                    </div>
                    {processedInvokeResponse.request.headers && (
                      <div>
                        <div className="requestDetails requestHeaders">{t('headers')}:</div>
                        <div className="requestDetails requestHeaders">
                          {Object.keys(processedInvokeResponse.request.headers).map((headerName) => (
                            <div key={headerName}>
                              {headerName}: {processedInvokeResponse.request.headers[headerName]}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </code>
                </pre>
              </div>
            </div>
          )}
          {hasConfidential && (
            <Button
              hasIconOnly
              className="toggleHidden"
              data-testid="toggleHidden"
              kind="ghost"
              iconDescription={!showHidden ? 'Hide access token' : 'Show access token'}
              tooltipAlignment={getBidiAlignLogical("end")}
              tooltipPosition="bottom"
              renderIcon={!showHidden ? View : ViewOff}
              onClick={() => {
                setShowHidden(!showHidden);
              }}
            />
          )}
          <Copier element=".testRequestContent" />
        </div>
      </div>
      <div className="testToolSection testToolResponse">
        <h3 className="labelText">
          {t('response')}
        </h3>
        <div dir='ltr' className={classNames('testResponseBody')}>
          {typeof processedInvokeResponse.statusCode === 'undefined' && <Loading className="invoking" small withOverlay={false} />}
          {typeof processedInvokeResponse.statusCode !== 'undefined' && (
            <div>
              <div className={classNames('responseDetails', 'responseStatus', `responseCode-${cleanUpKey(`${processedInvokeResponse.statusCode}`)}`)}>
                {processedInvokeResponse.statusCode >= 100 && processedInvokeResponse.statusCode <= 199 && (
                  <InformationFilled size={16} aria-label="Informational" className="cds--icon-information statusIcon" />
                )}
                {processedInvokeResponse.statusCode >= 200 && processedInvokeResponse.statusCode <= 299 && (
                  <CheckmarkFilled size={16} aria-label="Success" className="cds--icon-checkmark statusIcon" />
                )}
                {processedInvokeResponse.statusCode >= 300 && processedInvokeResponse.statusCode <= 399 && (
                  <WarningFilled size={16} aria-label="Redirection" className="cds--icon-warning statusIcon" />
                )}
                {processedInvokeResponse.statusCode >= 400 && <Misuse size={16} aria-label="Error" className="cds--icon-misuse statusIcon" />}
                <span className="statusCode">{` ${processedInvokeResponse.statusCode}`}</span> {` ${processedInvokeResponse.statusText}`}
                {processedInvokeResponse.statusInfo && <div className="boxout">{processedInvokeResponse.statusInfo}</div>}
              </div>
              <div>
                <div className={classNames('body', 'cds--snippet-container')}>
                  <div>
                    {processedInvokeResponse.statusCode === 0 && (
                      <div className="contrast responseDetails responseBody">
                        <div className="explorerCorsError">{corsMsg}</div>
                        <div className="explorerCertificateError">{t('explorer_check_certificate')}</div>
                        <a className="responseUrlLink" target="_blank" rel="noopener noreferrer" href={processedInvokeResponse.request.url}>
                          {filteredUrl}
                        </a>
                      </div>
                    )}
                    {processedInvokeResponse.statusCode * 1 !== 0 && (
                      <Tabs>
                        <TabList aria-label="response tabs">
                          {[
                            processedInvokeResponse.responseDataString && !processedInvokeResponse.isFileDownload && (
                              <Tab id="response_bodyTab" key="bodyTab" className="bodyTab" title={t('body')}>
                                {t('body')}{' '}
                              </Tab>
                            ),
                            processedInvokeResponse.headersAsString && (
                              <Tab id="response_headerTab" key="HeaderTab" className="HeaderTab" title={t('headers')}>
                                {t('headers')}
                              </Tab>
                            )
                          ].filter(Boolean)}
                        </TabList>
                        <TabPanels>
                          {[
                            processedInvokeResponse.responseDataString && !processedInvokeResponse.isFileDownload && (
                              <TabPanel key="bodyPanel">
                                <div className={classNames('cds--snippet', 'cds--snippet--multi', 'cds--snippet--expand')}>
                                  <pre className="contrast responseDetails responseBody">
                                    {!responseBody && <div className="spinner" />}

                                    {responseBody && (
                                      <CodeViewer data-testid="operation-example-generated" codeLanguage={contentFormat}>
                                        {responseBody}
                                      </CodeViewer>
                                    )}
                                  </pre>
                                  <Copier element=".responseBody" />
                                </div>
                              </TabPanel>
                            ),
                            processedInvokeResponse.headersAsString && (
                              <TabPanel key="headerPanel">
                                <div className={classNames('cds--snippet', 'cds--snippet--multi', 'cds--snippet--expand')}>
                                  <pre data-testid="response-headers" className="responseDetails responseHeaders">
                                    <code>
                                      {Object.keys(processedInvokeResponse.headers).map((headerName) => (
                                        <div key={headerName}>
                                          {headerName}: {processedInvokeResponse.headers[headerName]}
                                        </div>
                                      ))}
                                    </code>
                                  </pre>
                                  <Copier element=".responseHeaders" />
                                </div>
                              </TabPanel>
                            )
                          ].filter(Boolean)}
                        </TabPanels>
                      </Tabs>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default TestToolResponse;
