import React from 'react';
import { isBoolean, isNumber, isString } from 'lodash';
import { useTranslation } from 'react-i18next';
import ViewableJSONDisplay from './ViewableJSONDisplay.tsx';

function AsyncapiBindings({ bindings }) {
  const { t } = useTranslation();

  if (bindings.length === 0) {
    return null;
  }
  const bindingName = Object.keys(bindings)[0];
  const bindingInfo = bindings[bindingName].json();
  return (
    Object.keys(bindingInfo)?.length > 0 && (
      <div className="bindingContainer">
        <h6>{t('binding_details')}</h6>
        <div className="bindingTable">
          {Object.keys(bindingInfo).map((binding, index) => (
            <div className="keyValueDisplay" key={`${binding + index}`}>
              <div className="key bindingKey">{binding}</div>
              {(isString(bindingInfo[binding]) || isNumber(bindingInfo[binding]) || isBoolean(bindingInfo[binding])) && (
                <div className="value bindingValue">{String(bindingInfo[binding])}</div>
              )}
              {!isString(bindingInfo[binding]) && !isNumber(bindingInfo[binding]) && !isBoolean(bindingInfo[binding]) && (
                <div className="value bindingValue">
                  <ViewableJSONDisplay content={bindingInfo[binding]} />
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    )
  );
}

export default AsyncapiBindings;
