import React from 'react';
import { createRoot } from 'react-dom/client';
import ApiExplorerApp from './ApiExplorerApp';
import ThemeSync from './components/ThemeSync';

// Read theme set by portal dark-mode handler (if any) from localStorage
try {
  const LS_KEY = 'apiConnectExplorer.theme';
  const savedTheme = localStorage.getItem(LS_KEY);
  if (savedTheme) {
    window.apiConnectExplorer = window.apiConnectExplorer || {};
    window.apiConnectExplorer.options = window.apiConnectExplorer.options || {};
    window.apiConnectExplorer.options.theme = savedTheme;
  }

  // NOTE: dynamic runtime handling of storage/custom events is handled in ThemeSync
} catch {
  // ignore storage access errors (e.g., blocked in some contexts)
}

function getDomNode(selector) {
  // If not a string, assume we were passed a DOM Node already
  if (typeof selector !== 'string') {
    return selector;
  }

  return document.querySelector(selector);
}

let domNode;
if (window.apiConnectExplorer && window.apiConnectExplorer.attachPoint) {
  domNode = getDomNode(window.apiConnectExplorer.attachPoint);
} else {
  domNode = getDomNode('apiconnect-explorer');
}
const root = createRoot(domNode);

root.render(
  <>
    <ThemeSync />
    <ApiExplorerApp />
  </>
);
