import renderKafkaSnippet, { SnippetResult, SnippetOptions } from './kafka.ts';
import { ApiTypes, CodeLanguagesTypes } from './constants.ts';

/**
 * Function type for snippet generators
 */
// eslint-disable-next-line no-unused-vars
type SnippetGenerator = (codeLanguage: CodeLanguagesTypes, options: SnippetOptions) => SnippetResult;

const snippetFactory = (apiType: ApiTypes): SnippetGenerator => {
  switch (apiType) {
    case ApiTypes.Kafka: {
      return renderKafkaSnippet;
    }
    default: {
      throw new Error(`${apiType} is not supported`);
    }
  }
};

export default snippetFactory;
