import React from 'react';
import { Accordion, AccordionItem, TextInput } from '@carbon/react';
import { useTranslation } from 'react-i18next';
import DOMPurify from 'dompurify';

/**
 * OData-specific parameter component that handles:
 * - Entity keys (path parameters in OData format)
 * - System query options ($filter, $select, $expand, etc.)
 * - Custom query parameters
 */
export function TestToolODataParameters({ parameters, onChange = () => {} }) {
  const { t } = useTranslation();

  const handleParamChange = (name, value) => {
    // Sanitize input to prevent XSS
    const sanitizedValue = DOMPurify.sanitize(value, { ALLOWED_TAGS: [], ALLOWED_ATTR: [] });
    
    const updatedParams = {
      ...parameters,
      [name]: {
        ...parameters[name],
        value: sanitizedValue
      }
    };
    
    onChange({ parameterValues: updatedParams });
  };

  // Separate parameters by OData-specific categories
  const keyParams = [];
  const systemQueryParams = [];
  const customQueryParams = [];
  const headerParams = [];

  Object.keys(parameters).forEach((key) => {
    const param = parameters[key];
    
    if (param.in === 'path' || key === 'key') {
      // Entity key parameters
      keyParams.push({ key, ...param });
    } else if (param.in === 'query') {
      // System query options start with $
      if (param.name.startsWith('$')) {
        systemQueryParams.push({ key, ...param });
      } else {
        customQueryParams.push({ key, ...param });
      }
    } else if (param.in === 'header') {
      headerParams.push({ key, ...param });
    }
  });

  const getPlaceholder = (name, type) => {
    // Provide helpful placeholders for common OData parameters
    const placeholders = {
      'key': type === 'Edm.Guid' ? 'guid\'12345678-1234-1234-1234-123456789abc\'' : '123',
      '$filter': 'Price gt 100 and InStock eq true',
      '$select': 'Name,Price,Category',
      '$expand': 'Orders,Customer',
      '$orderby': 'Name desc',
      '$top': '10',
      '$skip': '0',
      '$count': 'true',
      '$search': 'laptop'
    };
    
    return placeholders[name] || '';
  };

  const renderParameter = (param) => {
    const { key, name, description, type, required } = param;
    const value = param.value || '';

    return (
      <div key={key} className="odata-parameter-item">
        <TextInput
          id={`odata-param-${key}`}
          labelText={
            <span>
              {name}
              {required && <span className="required-indicator"> *</span>}
              {type && <span className="param-type"> ({type})</span>}
            </span>
          }
          helperText={description}
          value={value}
          onChange={(e) => handleParamChange(key, e.target.value)}
          placeholder={getPlaceholder(name, type)}
          data-testid={`odata-param-${key}`}
        />
      </div>
    );
  };

  return (
    <div className="odata-parameters">
      <Accordion>
        {/* Entity Key Section */}
        {keyParams.length > 0 && (
          <AccordionItem title={t('entity_key')} open>
            <div className="odata-parameters-section">
              <p className="odata-section-description">
                {t('odata_key_description', 'Specify the key value to access a specific entity. Leave empty to query the collection.')}
              </p>
              {keyParams.map(renderParameter)}
            </div>
          </AccordionItem>
        )}

        {/* System Query Options Section */}
        {systemQueryParams.length > 0 && (
          <AccordionItem title={t('odata_system_query_options')}>
            <div className="odata-parameters-section">
              <p className="odata-section-description">
                {t('odata_system_query_description', 'OData standardized query options for filtering, sorting, pagination, and field selection.')}
              </p>
              {systemQueryParams.map(renderParameter)}
            </div>
          </AccordionItem>
        )}

        {/* Custom Query Parameters Section */}
        {customQueryParams.length > 0 && (
          <AccordionItem title={t('custom_query_parameters')}>
            <div className="odata-parameters-section">
              {customQueryParams.map(renderParameter)}
            </div>
          </AccordionItem>
        )}

        {/* Header Parameters Section */}
        {headerParams.length > 0 && (
          <AccordionItem title={t('headers')}>
            <div className="odata-parameters-section">
              {headerParams.map(renderParameter)}
            </div>
          </AccordionItem>
        )}
      </Accordion>
    </div>
  );
}

export default TestToolODataParameters;
